import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';


const ProjectDetail = () => {
  const { projectId } = useParams();
  const [activeSection, setActiveSection] = useState('overview');

  // Scroll to top on mount
  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [projectId]);

  // Handle Scroll Spy
  useEffect(() => {
    const handleScroll = () => {
      const sections = ['overview', 'innovations', 'impact', 'contact'];
      const scrollPosition = window.scrollY + 200;

      for (const section of sections) {
        const element = document.getElementById(section);
        if (element && element.offsetTop <= scrollPosition && (element.offsetTop + element.offsetHeight) > scrollPosition) {
          setActiveSection(section);
        }
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const scrollToSection = (id) => {
    const element = document.getElementById(id);
    if (element) {
      const offset = 120;
      const elementPosition = element.getBoundingClientRect().top;
      const offsetPosition = elementPosition + window.pageYOffset - offset;
      window.scrollTo({ top: offsetPosition, behavior: 'smooth' });
    }
  };

  // --- UPDATED DATA WITH YOUR SPECIFIC PROJECT DETAILS ---
  const projectsData = {
    'intelligent-sensor': {
      title: 'Pollution Intelligence Network',
      subtitle: 'AI-Powered Hyperlocal Monitoring',
      tagline: 'Sensing. Predicting. Protecting.',
      mainImage: 'https://images.unsplash.com/photo-1621905252507-b35492cc74b4?q=80&w=2069&auto=format&fit=crop',
      description: 'A scalable LoRa-based network designed not just to monitor, but to predict air quality trends using Artificial Intelligence.',
      fullDescription: `
        We have deployed a validation-ready network that goes beyond simple sensing. By utilizing LoRa technology for long-range communication and advanced AI models, we provide a 4-day AQI forecast. This allows citizens to plan their activities based on future air quality, not just current readings.
      `,
      // "Key Features" replaced with "Core Innovations" based on your inputs
      innovations: [
        { 
          title: 'Comprehensive Sensing', 
          desc: 'Simultaneous detection of PM2.5, PM10, CO, NO2, O3, and NH3 for a complete pollution profile.',
          icon: '🔬' 
        },
        { 
          title: '4-Day AI Forecasting', 
          desc: 'Machine learning algorithms analyze trends to predict AQI levels up to 96 hours in advance.',
          icon: '🤖' 
        },
        { 
          title: 'Personalized Health Risk', 
          desc: 'Dynamic health assessments that warn specific at-risk groups based on real-time data.',
          icon: '❤️' 
        },
        { 
          title: 'LoRa Scalability', 
          desc: 'Long-range, low-power network architecture allows coverage of entire districts with minimal hardware.',
          icon: '📡' 
        }
      ],
      impacts: [
        { label: 'Respiratory Health', value: 'Live Alerts for Asthma' },
        { label: 'Prediction Window', value: '4-Days Ahead' },
        { label: 'Pollutants Tracked', value: '6 Key Parameters' },
        { label: 'Network Type', value: 'LoRaWAN Mesh' }
      ]
    },
    'water-level': {
      title: 'River Watch & Flood Alert',
      subtitle: 'Deep Learning Flood Forecasting',
      tagline: 'Predicting the flow. Protecting Kalady.',
      mainImage: 'https://images.unsplash.com/photo-1440404653325-ab127d49abc1?q=80&w=2070&auto=format&fit=crop', // River/Flood image
      description: 'A dedicated flood forecasting system for the Kalady region using LSTM Neural Networks and custom-built weather stations.',
      fullDescription: `
        This project integrates multi-source data—dam operations, real-time rainfall, and historical patterns—into a comprehensive LSTM Neural Network. The result is a highly accurate system capable of predicting river levels 6 hours in advance, giving authorities crucial time to act.
      `,
      innovations: [
        { 
          title: 'LSTM Neural Network', 
          desc: 'Advanced Deep Learning models trained on historical data to predict flood risks with high accuracy.',
          icon: '🧠' 
        },
        { 
          title: '6-Hour Prediction', 
          desc: 'Provides a critical 6-hour lead time for evacuation and preparation before water levels peak.',
          icon: '⏱️' 
        },
        { 
          title: 'Custom AWS Hardware', 
          desc: 'Proprietary Automatic Weather Station measuring Rainfall, Wind, Temperature, and Humidity.',
          icon: '⛈️' 
        },
        { 
          title: 'Target Location: Kalady', 
          desc: 'Models are specifically calibrated for the topography and river dynamics of the Kalady region.',
          icon: '📍' 
        }
      ],
      impacts: [
        { label: 'AI Model', value: 'LSTM Network' },
        { label: 'Forecast Lead Time', value: '6 Hours' },
        { label: 'Data Sources', value: 'Dam & Rainfall' },
        { label: 'Hardware', value: 'Custom AWS' }
      ]
    },
    'digital-water': {
      title: 'Digital Water Distribution',
      subtitle: 'Community-First Water Management',
      tagline: 'Collaborative solutions for efficient distribution.',
      mainImage: 'https://images.unsplash.com/photo-1605218457336-9276c1272bd8?q=80&w=2070&auto=format&fit=crop', // Pipes/Water infra
      description: 'A digital system built on extensive ground studies to monitor and optimize local water distribution effectively.',
      fullDescription: `
        Technology works best when it understands the people it serves. We conducted comprehensive ground studies, engaging with KWA officials, Panchayat authorities, and community representatives. This system digitizes the water network to ensure fair distribution and rapid leak detection.
      `,
      innovations: [
        { 
          title: 'Stakeholder Collaboration', 
          desc: 'Built on requirements gathered directly from KWA officials and Panchayat authorities.',
          icon: '🤝' 
        },
        { 
          title: 'Real-Time Web Platform', 
          desc: 'A centralized dashboard for officials to track live multi-parameter data from all stations.',
          icon: '💻' 
        },
        { 
          title: 'Distribution Logic', 
          desc: 'Algorithms that analyze flow data to ensure equitable water supply across different wards.',
          icon: '⚖️' 
        },
        { 
          title: 'Community Feedback', 
          desc: 'Integrated channels for local residents to report issues, validating the digital data.',
          icon: '🗣️' 
        }
      ],
      impacts: [
        { label: 'Partners', value: 'KWA & Panchayat' },
        { label: 'Platform', value: 'Web Dashboard' },
        { label: 'Focus', value: 'Equitable Supply' },
        { label: 'Study Type', value: 'Ground & Technical' }
      ]
    },
     'startup-skill': {
      title: 'Edu-Tech & Training',
      subtitle: 'Empowering the Next Gen',
      tagline: 'Hands-on mastery of IoT & Environment.',
      mainImage: 'https://images.unsplash.com/photo-1517048676732-d65bc937f952?q=80&w=2070&auto=format&fit=crop', // Workshop/Students
      description: 'Specialized training programs and workshops designed to bridge the gap between academic theory and industrial IoT application.',
      fullDescription: `
        We don't just build systems; we build capabilities. Our training programs focus specifically on IoT and Environmental Monitoring. Students gain practical experience with sensors, microcontrollers, and cloud platforms, preparing them for the future of connected technology.
      `,
      innovations: [
        { 
          title: 'IoT Workshops', 
          desc: 'Intensive sessions on sensor interfacing, microcontroller programming, and data transmission.',
          icon: '🛠️' 
        },
        { 
          title: 'Environmental Focus', 
          desc: 'Specialized curriculum on calibrating and deploying air and water quality sensors.',
          icon: '🌿' 
        },
        { 
          title: 'Real-World Deployment', 
          desc: 'Students participate in the actual deployment of our monitoring nodes in the field.',
          icon: '🚀' 
        },
        { 
          title: 'Data Science Basics', 
          desc: 'Introduction to analyzing sensor data using Python and basic ML concepts.',
          icon: '📊' 
        }
      ],
      impacts: [
        { label: 'Focus Area', value: 'IoT & Environment' },
        { label: 'Method', value: 'Hands-on Workshop' },
        { label: 'Outcome', value: 'Field Ready' },
        { label: 'Target', value: 'Students' }
      ]
    },
  };

  const project = projectsData[projectId];

  if (!project) {
    return (
      <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', flexDirection: 'column', background: '#f8fafc' }}>
        <h2 style={{ color: '#334155', marginBottom: '1rem' }}>Project Loading or Not Found...</h2>
        <Link to="/" style={{ padding: '0.75rem 1.5rem', background: '#0ea5e9', color: 'white', borderRadius: '2rem', textDecoration: 'none' }}>
          Back to Home
        </Link>
      </div>
    );
  }

  // --- LIGHT THEME STYLES ---
  const styles = {
    stickyNav: {
      position: 'sticky',
      top: '0', 
      zIndex: 100,
      backgroundColor: 'rgba(255, 255, 255, 0.9)',
      backdropFilter: 'blur(10px)',
      borderBottom: '1px solid #e2e8f0',
      boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.05)',
    },
    navItem: (isActive) => ({
      padding: '1.2rem 2rem',
      color: isActive ? '#0284c7' : '#64748b',
      fontWeight: isActive ? 700 : 500,
      borderBottom: isActive ? '3px solid #0284c7' : '3px solid transparent',
      cursor: 'pointer',
      fontSize: '0.95rem',
      transition: 'all 0.3s ease',
      whiteSpace: 'nowrap'
    }),
    sectionTitle: {
      fontSize: '2.5rem',
      fontWeight: 800,
      color: '#0f172a',
      marginBottom: '1rem',
      textAlign: 'center',
      letterSpacing: '-0.02em'
    },
    card: {
      background: 'white',
      borderRadius: '1rem',
      border: '1px solid #f1f5f9',
      boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.05)',
      padding: '2rem',
      transition: 'all 0.3s ease',
      height: '100%',
      display: 'flex',
      flexDirection: 'column'
    },
    statBox: {
      background: '#f0f9ff',
      padding: '1.5rem',
      borderRadius: '0.75rem',
      textAlign: 'center',
      border: '1px solid #bae6fd'
    }
  };

  return (
    <div style={{ background: '#ffffff', minHeight: '100vh', fontFamily: '"Inter", sans-serif', color: '#334155' }}>
      
      {/* 1. HERO SECTION */}
      <section style={{ 
        position: 'relative', 
        paddingTop: '6rem',
        paddingBottom: '4rem',
        background: 'radial-gradient(circle at top right, #f0f9ff 0%, #ffffff 40%)'
      }}>
        <div style={{ maxWidth: '80rem', margin: '0 auto', padding: '0 2rem', display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(450px, 1fr))', alignItems: 'center', gap: '4rem' }}>
          
          <div>
            <div style={{ display: 'inline-block', padding: '0.5rem 1rem', background: '#e0f2fe', color: '#0369a1', borderRadius: '2rem', fontWeight: 600, fontSize: '0.875rem', marginBottom: '1.5rem' }}>
               Project Detail
            </div>
            <h1 style={{ fontSize: 'clamp(2.5rem, 5vw, 4rem)', fontWeight: 900, color: '#0f172a', lineHeight: 1.1, marginBottom: '1.5rem' }}>
              {project.title}
            </h1>
            <p style={{ fontSize: '1.25rem', color: '#64748b', marginBottom: '2.5rem', lineHeight: 1.6 }}>
              {project.description}
            </p>
            <div style={{ display: 'flex', gap: '1rem' }}>
              <button onClick={() => scrollToSection('innovations')} style={{ padding: '1rem 2rem', background: '#0f172a', color: 'white', borderRadius: '0.5rem', fontWeight: 600, border: 'none', cursor: 'pointer' }}>
                Key Innovations
              </button>
              <Link to="/" style={{ padding: '1rem 2rem', background: 'white', color: '#0f172a', borderRadius: '0.5rem', fontWeight: 600, border: '1px solid #cbd5e1', cursor: 'pointer', textDecoration: 'none' }}>
                Back to List
              </Link>
            </div>
          </div>

          <div style={{ position: 'relative' }}>
            <div style={{ position: 'absolute', inset: '1rem', background: '#0ea5e9', filter: 'blur(40px)', opacity: 0.2, borderRadius: '2rem' }}></div>
            <img 
              src={project.mainImage} 
              alt={project.title} 
              style={{ width: '100%', borderRadius: '1.5rem', boxShadow: '0 20px 40px -10px rgba(0,0,0,0.1)', position: 'relative', zIndex: 10 }} 
            />
          </div>
        </div>
      </section>

      {/* 2. STICKY NAV */}
      <div style={styles.stickyNav}>
        <div style={{ maxWidth: '80rem', margin: '0 auto', display: 'flex', justifyContent: 'center', overflowX: 'auto' }}>
          {['Overview', 'Innovations', 'Impact', 'Contact'].map((item) => (
            <div key={item} onClick={() => scrollToSection(item.toLowerCase())} style={styles.navItem(activeSection === item.toLowerCase())}>
              {item}
            </div>
          ))}
        </div>
      </div>

      <div style={{ maxWidth: '72rem', margin: '0 auto', padding: '0 2rem' }}>

        {/* 3. OVERVIEW */}
        <section id="overview" style={{ padding: '6rem 0', borderBottom: '1px solid #f1f5f9' }}>
          <div style={{ maxWidth: '50rem', margin: '0 auto', textAlign: 'center' }}>
            <h3 style={{ color: '#0ea5e9', fontWeight: 700, letterSpacing: '1px', textTransform: 'uppercase', fontSize: '0.9rem', marginBottom: '1rem' }}>Our Mission</h3>
            <h2 style={{ fontSize: '2rem', fontWeight: 800, color: '#1e293b', marginBottom: '1.5rem' }}>
              {project.tagline}
            </h2>
            <p style={{ fontSize: '1.15rem', lineHeight: 1.8, color: '#475569' }}>
              {project.fullDescription}
            </p>
          </div>
        </section>

        {/* 4. INNOVATIONS (Dynamic Grid) */}
        <section id="innovations" style={{ padding: '6rem 0', borderBottom: '1px solid #f1f5f9' }}>
          <h2 style={styles.sectionTitle}>Key Innovations</h2>
          <p style={{ textAlign: 'center', color: '#64748b', marginBottom: '4rem' }}>
            Technological breakthroughs powering this solution.
          </p>

          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '2rem' }}>
            {project.innovations && project.innovations.map((item, idx) => (
              <div 
                key={idx} 
                style={styles.card}
                onMouseEnter={(e) => { e.currentTarget.style.transform = 'translateY(-5px)'; e.currentTarget.style.borderColor = '#bae6fd'; }}
                onMouseLeave={(e) => { e.currentTarget.style.transform = 'translateY(0)'; e.currentTarget.style.borderColor = '#f1f5f9'; }}
              >
                <div style={{ width: '3.5rem', height: '3.5rem', background: '#e0f2fe', borderRadius: '0.75rem', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.75rem', marginBottom: '1.5rem', color: '#0284c7' }}>
                  {item.icon}
                </div>
                <h3 style={{ fontSize: '1.25rem', fontWeight: 700, color: '#1e293b', marginBottom: '0.75rem' }}>
                  {item.title}
                </h3>
                <p style={{ color: '#64748b', lineHeight: 1.6, fontSize: '1rem' }}>
                  {item.desc}
                </p>
              </div>
            ))}
          </div>
        </section>

        {/* 5. IMPACT & SPECS */}
        <section id="impact" style={{ padding: '6rem 0' }}>
          <div style={{ background: '#f8fafc', borderRadius: '2rem', padding: '4rem 2rem' }}>
            <h2 style={styles.sectionTitle}>Project Impact</h2>
            <p style={{ textAlign: 'center', color: '#64748b', marginBottom: '3rem' }}>
              Measurable outcomes and technical specifics.
            </p>
            
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '2rem' }}>
              {project.impacts && project.impacts.map((stat, idx) => (
                <div key={idx} style={styles.statBox}>
                  <div style={{ fontSize: '0.9rem', fontWeight: 600, color: '#64748b', marginBottom: '0.5rem', textTransform: 'uppercase' }}>
                    {stat.label}
                  </div>
                  <div style={{ fontSize: '1.25rem', fontWeight: 800, color: '#0284c7' }}>
                    {stat.value}
                  </div>
                </div>
              ))}
            </div>
          </div>
        </section>

        {/* 6. CONTACT */}
        <section id="contact" style={{ padding: '4rem 0 8rem 0', textAlign: 'center' }}>
          <h2 style={{ fontSize: '2rem', fontWeight: 800, color: '#1e293b', marginBottom: '1rem' }}>
            Interested in collaboration?
          </h2>
          <p style={{ color: '#64748b', marginBottom: '2rem' }}>
            We are open to working with government bodies and educational institutions.
          </p>
          <a href="mailto:contact@aiiot.edu" style={{ display: 'inline-block', padding: '1rem 3rem', background: '#0f172a', color: 'white', fontWeight: 600, borderRadius: '3rem', textDecoration: 'none', transition: 'transform 0.2s' }}>
            Get in Touch
          </a>
        </section>

      </div>
    </div>
  );
};

export default ProjectDetail;
